#!/usr/bin/env python3
"""Assemble bounded source reviews; never infer full conversion from extraction."""
import json
from pathlib import Path
BASE=Path(__file__).parent
inventory=json.loads((BASE/'source-reconciliation-2026-10-13.json').read_text())
units={u['source_title_id']:u for u in inventory['source_units']}
sources={}
file_scopes={}

def scope(reader,pages,status,finding,credit=None,title=None,year=None):
    file_scopes[reader]={'reviewed_pages':pages,'status':status,'finding':finding,'actual_credit':credit,'actual_title':title,'actual_year':year}

def rule(name,inputs,entry,exit,missing,data,component=False):
    return dict(name=name,complete=False,completeness_kind=('Sizing or educational component; not a standalone trading strategy' if component else 'Source-supported clauses; whole original study not reproduced'),inputs=inputs,entry=entry,exit=exit,missing=missing,data_requirement=data)

def add(sid,title,kind,cats,summary,status,credit,year,evidence,outline=(),rules=(),limits=None):
    u=units[sid]
    out=[]
    for rid,pages,finding in evidence:
        f=next(f for f in u['files'] if f['reader_id']==rid)
        out.append({'file':f['reader_path'].split('/')[-1],'reader_id':rid,'page_range':pages,'page_numbering':'PDF pages; printed pagination stated in finding when checked','finding':finding})
    sources[sid]={'id':sid,'inventory_title':u['inventory_title'],'title':title,'entry_kind_label':kind,'summary':summary,'categories':cats,'category_evidence':[{'category':c,'basis':'Bounded source evidence below; no claim that every section has been reviewed'} for c in cats], 'source_identity':{'title':title,'credit':credit,'year':year,'identity_scope':'Actual title/copyright/byline where stated in evidence; collection and scan limits remain explicit'}, 'files':u['files'],'review':{'status':status,'status_label':{'partial_rules':'Partial rules reviewed','sizing_component':'Sizing component reviewed','reviewed_non_rule':'Educational content reviewed','contents_only':'Contents and samples reviewed','subject_preview':'Bounded preview reviewed','scan_limited':'Scanned source: bounded visual review'}.get(status,status),'full_book_review':False,'performance_verified':False,'evidence':out,'outline':[{'label':a,'detail':b} for a,b in outline],'rules':list(rules),'reading_limits':limits or 'Only the listed source pages were checked. This is not a complete book review, conversion certificate, or reproduction of its published performance.'},'missing':[]}

