rule110=rule('Simple 110-day stock breakout example',['110-day channel breakout','Weekly volatility','No more than 1% equity risk'], 'Buy a 110-day channel breakout.', 'Weekly-volatility worst-case exit and a trail from the close.', ['Weekly volatility measure, lookback and multiplier are not specified in the reviewed paragraph','Signal/fill timing, stock population and full sizing/portfolio rules remain incomplete'], ['Authentic stock OHLC and defined historical stock universe after completing missing rules'])
add(ST,'Super Trader','Book',['psychology','money-management','rule-based'], 'Organizes trading around work on the trader, a business plan, system development, position sizing and consistent execution. Its random-entry example uses a 20-day ATR convention, distinct from Trade Your Way’s EMA10. The later 110-day stock breakout is a simplifying illustration with an incomplete weekly-volatility exit.', 'partial_rules','Van K. Tharp',2009,[(sr,[[4,7]],'Copyright 2009, title, ISBN and five-part contents checked.'),(sr,[[162,162],[167,169]],'Printed pages 148 and 153–155: ten-commodity random-entry experiment, three times 20-day ATR, close-based one-way trail; illustrative stop discussions.'),(sr,[[227,227]],'Printed page 213: 110-day stock breakout example; weekly-volatility exit is not fully defined.')],[('Work on yourself','Identify beliefs and recurring trading mistakes.'),('Business plan and system','Relate system design to personal goals and constraints.'),('Sizing and performance','Study risk units, sizing and execution discipline as separate components.')],[random20,rule110])
scope(sr,[[4,7],[162,162],[167,169],[227,227]],'partial_rules','20-day ATR random-entry example and incomplete 110-day stock example checked; no original performance reproduction.','Van K. Tharp','Super Trader',2009)
falsebreak=rule('False-breakout entry worksheet',['Today makes a 20-day low for long; invert highs/lows for short','Previous low not within the last five days','Buy stop eight ticks above the previous 20-day low, valid today only'], 'Use the eight-tick stop entry; the worksheet additionally permits re-entry at the original price on day one or two only.', 'Initial GTC stop just under today’s low for long (invert for short).', ['No complete final profit-taking exit is supplied in the checked worksheet','Tick units and fill ordering must be authentic to the intended futures contract','The stated two-to-three-hours-or-days holding description is not a deterministic exit rule'], ['Contract-specific tick data and intraday execution evidence, or an explicitly labeled daily OHLC adaptation after missing clauses are resolved'])
