add(sid,'Introduction to Position Sizing: The Secrets of the Masters Trading Game','Game guide',['money-management','psychology','rule-based'],'Uses a simulated R-multiple game to show how edge, position sizing, objectives and losing streaks interact. R is the initial amount at risk; the mean of an R-multiple distribution measures expectancy. Game probabilities are designed teaching inputs and are not observed stock or Nifty backtest results.', 'sizing_component','Van K. Tharp',None,[(rid,[[1,5],[9,17]],'Title, R definition, toy outcome distribution, game goals and changing game levels read.')],[('Define one R','Measure a trade relative to its initial stop risk.'),('Describe outcomes','Keep wins and losses in R-multiples.'),('Choose sizing','Study how sizing changes a simulated path without changing the game’s stated edge.')],[rule('R-multiple game expectancy',['Stated toy probabilities and R outcomes'],'No historical market entry.','No historical market exit.',['Simulated teaching distribution, not empirical market data','Game outcomes do not define a stock strategy'],['Only the game’s stated distribution is needed for the educational calculation'],True)])
scope(rid,[[1,5],[9,17]],'sizing_component','R-multiple teaching game reviewed; hypothetical probability distribution is not a market backtest.','Van K. Tharp','Introduction to Position Sizing: The Secrets of the Masters Trading Game',None)

