add(sid,'Technical Congress 2006 — presentation collection','Presentation collection',['psychology','money-management','rule-based'],'Five short presentation PDFs cover trader objectives, broad-market beliefs, a system-design sequence and stock-efficiency screening. The efficiency example measures price change relative to ATR, but its time period, full ranking policy and several chart-quality exclusions remain discretionary. A suggested open entry appears as a question in the source, not a fully defined execution rule.', 'partial_rules','Van K. Tharp',2006,[(slide_ids[0],[[1,7]],'Background and design-step slides checked.'),(slide_ids[1],[[1,8]],'Eight-step system outline; open-entry text is a question; 25% trailing-stop example is a component.'),(slide_ids[2],[[1,6]],'Self-assessment, constraints and objectives.'),(slide_ids[3],[[1,6]],'Dated macro beliefs and regime discussion, not a current forecast.'),(slide_ids[4],[[1,13]],'Stock efficiency and example charts; bursts, choppiness, gaps and parabolic moves are rejected by qualitative judgment.')],[('Start with objectives','Assess beliefs, time, resources and personal constraints.'),('Screen stock efficiency','Relative movement per ATR is a screening component.'),('Review chart quality','Qualitative exclusions must be made reproducible before a faithful test.')],[rule('Efficiency-stock screening component',['Price change divided by ATR over the chosen period','25% trailing stop example'],'Exact lookback, stock ranking, universe, qualitative exclusions and entry time are not fixed.','A 25% trail is an illustrated exit component, not a complete strategy.',['Time period and rank cutoffs','Historical stock membership','Objective versions of qualitative chart exclusions','Entry timing remains a question in the source'],['Authentic individual-stock OHLC and a declared historical universe after source clauses are completed'])])
